insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_madv7_v1'
from (values
('111.30.c.2.A',3,'A Venn diagram shows rational numbers as a large circle. Where would the irrational numbers be drawn?','["outside the rational circle but inside the real numbers", "inside the integer circle", "inside the whole-number circle", "overlapping the natural numbers"]'::jsonb,0,'Irrational numbers are real but not rational, so they sit outside the rational set.','original'),
('111.30.c.2.A',3,'Which statement about the real number system is true?','["Every rational number is an integer.", "Every integer is also a rational number.", "No decimal is a real number.", "Every irrational number is a whole number."]'::jsonb,1,'An integer n can be written as n/1.','original'),
('111.30.c.2.B',3,'Between which two consecutive integers does the square root of 38 lie?','["7 and 8", "19 and 20", "6 and 7", "5 and 6"]'::jsonb,2,'36 < 38 < 49, so the root is between 6 and 7.','original'),
('111.30.c.2.B',3,'Which is the best estimate of pi to the nearest hundredth for placing on a number line?','["3.00", "3.40", "3.41", "3.14"]'::jsonb,3,'Pi is about 3.14159.','original'),
('111.30.c.2.B',4,'On a number line, the square root of 20 is closest to which point?','["4.5", "10", "5", "4"]'::jsonb,0,'4.5 squared is 20.25, which is very near 20.','original'),
('111.30.c.2.C',3,'Write 4,200,000 in scientific notation.','["4.2 × 10⁷", "4.2 × 10⁶", "0.42 × 10⁶", "42 × 10⁵"]'::jsonb,1,'Move the decimal point six places to get 4.2.','original'),
('111.30.c.2.C',3,'What is 3.7 × 10⁻³ in standard decimal notation?','["3,700", "0.00037", "0.0037", "0.037"]'::jsonb,2,'A negative exponent of 3 moves the decimal three places left.','original'),
('111.30.c.2.D',4,'Which value is greatest?','["3.14", "√10", "π", "3.2"]'::jsonb,3,'√10 ≈ 3.16 and π ≈ 3.14, both less than 3.2.','original'),
('111.30.c.3.A',3,'What is -3/4 ÷ 3/8?','["-2", "-9/32", "-1/2", "2"]'::jsonb,0,'Multiply by the reciprocal: -3/4 × 8/3 = -2.','original'),
('111.30.c.3.A',3,'What is -2.5 × (-1.6)?','["-0.4", "4", "-4", "0.4"]'::jsonb,1,'A negative times a negative is positive: 2.5 × 1.6 = 4.','original'),
('111.30.c.3.A',2,'What is -9.4 + 5.7?','["15.1", "3.7", "-3.7", "-15.1"]'::jsonb,2,'The larger absolute value is negative, so the sum is negative.','original'),
('111.30.c.3.B',4,'A diver at -18.5 feet rises 6.25 feet and then descends 4 feet. What is the new depth?','["-8.25 feet", "-20.5 feet", "-28.75 feet", "-16.25 feet"]'::jsonb,3,'-18.5 + 6.25 - 4 = -16.25.','original'),
('111.30.c.3.B',3,'Four bottles each hold 1 1/2 cups. A cook pours out 2 3/4 cups in total. How much is left?','["3 1/4 cups", "1 1/4 cups", "3 3/4 cups", "8 3/4 cups"]'::jsonb,0,'4 × 1 1/2 = 6, and 6 - 2 3/4 = 3 1/4.','original'),
('111.30.c.4.A',4,'A tablet costs $250 and its price rises by 20%. A week later the new price drops by 20%. What is the final price?','["$260", "$240", "$200", "$250"]'::jsonb,1,'250 × 1.2 = 300, then 300 × 0.8 = 240.','original'),
('111.30.c.4.A',3,'A town''s population grew from 8,000 to 9,200. What is the percent increase?','["1.5%", "13%", "15%", "12%"]'::jsonb,2,'1,200 ÷ 8,000 = 0.15.','original'),
('111.30.c.4.B',3,'What is the simple interest on $600 at 5% per year for 3 years?','["$93.15", "$30", "$180", "$90"]'::jsonb,3,'I = Prt = 600 × 0.05 × 3 = 90.','original'),
('111.30.c.4.B',4,'$1,000 earns 10% interest compounded annually. How much is it worth after 2 years?','["$1,210", "$1,020", "$1,100", "$1,200"]'::jsonb,0,'1,000 × 1.1 × 1.1 = 1,210.','original'),
('111.30.c.4.C ',3,'A $80 pair of shoes is on sale for 25% off and you also have a $5 coupon taken off the sale price. What do you pay?','["$60", "$55", "$50", "$75"]'::jsonb,1,'25% off gives $60, and the coupon takes it to $55.','original'),
('111.30.c.4.C ',3,'Which describes a rebate?','["a tax on the item", "a free gift with no purchase", "money returned to you after you buy and submit proof", "a discount taken at the register"]'::jsonb,2,'A rebate is paid back after the sale.','original'),
('111.30.c.4.D',3,'Two loans are for the same amount at the same rate. One lasts 2 years and the other lasts 5 years. Which usually costs more in total interest?','["It cannot be known", "the 2-year loan", "They always cost the same", "the 5-year loan"]'::jsonb,3,'A longer term accrues interest for more time.','original'),
('111.30.c.4.D',4,'For the same loan length, which rate gives the lowest cost of credit?','["4%", "12%", "6%", "9%"]'::jsonb,0,'Lower rates produce less interest.','original'),
('111.30.c.4.E',3,'A loan requires $150 a month for 24 months. What is the total repaid?','["$2,400", "$3,600", "$360", "$174"]'::jsonb,1,'150 × 24 = 3,600.','original'),
('111.30.c.4.E',4,'A $2,000 loan is repaid with 12 payments of $185. How much interest was paid?','["$12", "$2,220", "$220", "$185"]'::jsonb,2,'12 × 185 = 2,220, and 2,220 - 2,000 = 220.','original'),
('111.30.c.4.F ',3,'Why does saving a small amount every month for many years grow so much?','["Saved money is never taxed or fee-free by law.", "Inflation always stops.", "Banks stop charging fees.", "Earnings are added to the balance and then earn interest too."]'::jsonb,3,'Compounding makes earlier deposits grow the most.','original'),
('111.30.c.4.F ',3,'Who is likely to end up with more at retirement, assuming the same monthly deposit and rate?','["the person who starts saving at age 22", "the person who saves nothing early", "the person who starts at age 42", "They always end equal"]'::jsonb,0,'More time means more compounding.','original'),
('111.30.c.4.G',3,'A four-year college costs $18,000 per year. A family can contribute $20,000 total. How much more is needed in total?','["$38,000", "$52,000", "$72,000", "$16,000"]'::jsonb,1,'4 × 18,000 = 72,000, and 72,000 - 20,000 = 52,000.','original'),
('111.30.c.4.G',3,'A two-year program costs $6,500 per year. Scholarships cover $4,000 in all. How much remains to pay?','["$2,500", "$17,000", "$9,000", "$13,000"]'::jsonb,2,'2 × 6,500 = 13,000, and 13,000 - 4,000 = 9,000.','original'),
('111.30.c.5.A',2,'Pi is the ratio of a circle''s circumference to its:','["area", "height", "radius", "diameter"]'::jsonb,3,'C ÷ d is pi for every circle.','original'),
('111.30.c.5.A',3,'A circular lid has a diameter of 10 cm and a circumference of about 31.4 cm. What does 31.4 ÷ 10 estimate?','["pi", "the area", "the volume", "the radius"]'::jsonb,0,'Circumference over diameter gives pi.','original'),
('111.30.c.5.B',3,'Which is true of two similar triangles?','["They have the same perimeter.", "Their corresponding angles are equal and corresponding sides are proportional.", "Their areas are equal.", "Their side lengths are equal."]'::jsonb,1,'Similar shapes keep shape but may differ in size.','original'),
('111.30.c.5.B',3,'Triangle P has sides 3, 4, 5. Which triangle is similar to it?','["4, 5, 6", "5, 6, 7", "6, 8, 10", "3, 4, 6"]'::jsonb,2,'6, 8, 10 is each side times 2.','original'),
('111.30.c.5.C',3,'A blueprint scale is 1 cm = 2.5 m. A room is 6 cm long on the blueprint. What is its real length?','["8.5 m", "2.4 m", "12 m", "15 m"]'::jsonb,3,'6 × 2.5 = 15.','original'),
('111.30.c.5.C',4,'Two similar rectangles have widths 4 and 10. If the smaller has length 6, what is the larger one''s length?','["15", "10", "14", "24"]'::jsonb,0,'The scale factor is 10 ÷ 4 = 2.5, so 6 × 2.5 = 15.','original'),
('111.30.c.5.D',3,'A shape is dilated and its angles stay the same while its sides change. Which statement is true?','["The image is congruent to the original.", "The image is similar but not congruent to the original.", "The angles must be larger.", "The shape reflected."]'::jsonb,1,'Dilation keeps angle measures but changes size.','original'),
('111.30.c.5.D',3,'Which transformation of a figure changes its size?','["translation", "rotation", "dilation", "reflection"]'::jsonb,2,'The other three preserve size.','original'),
('111.30.c.5.E',4,'A dilation with scale factor 3 centered at the origin sends (2, 5) to:','["(5, 8)", "(6, 5)", "(2/3, 5/3)", "(6, 15)"]'::jsonb,3,'Multiply each coordinate by 3.','original'),
('111.30.c.5.E',4,'A dilation centered at the origin uses scale factor 1/2. Which point is the image of (8, -4)?','["(4, -2)", "(16, -8)", "(4, 2)", "(8, -2)"]'::jsonb,0,'Halve each coordinate.','original'),
('111.30.c.6.A',3,'A spinner has 3 colors and a coin has 2 sides. How many outcomes are in the sample space for spinning once and flipping once?','["3", "6", "5", "2"]'::jsonb,1,'3 × 2 = 6.','original'),
('111.30.c.6.A',3,'Which tool lists every outcome of two independent stages by branching?','["histogram", "circle graph", "tree diagram", "scatter plot"]'::jsonb,2,'Branches show each choice.','original'),
('111.30.c.6.B',3,'Which is a fair way to simulate a 1-in-4 chance event?','["draw from a bag with 3 marked of 4", "roll one die and count a 1 or 2", "flip a coin once", "draw a card from four equal cards, one marked"]'::jsonb,3,'One marked card out of four equal cards has probability 1/4.','original'),
('111.30.c.6.B',3,'To simulate a 50% chance, which tool works?','["flipping a fair coin", "drawing 1 of 5 equal cards", "spinning a 3-color equal spinner", "rolling a die and counting a 6"]'::jsonb,0,'A fair coin has two equally likely results.','original'),
('111.30.c.6.C',3,'A spinner lands on blue 18 times in 60 spins. What is the experimental probability of blue?','["6/10", "3/10", "1/6", "18/42"]'::jsonb,1,'18 ÷ 60 = 3/10.','original'),
('111.30.c.6.C',3,'Using a result of 12 heads in 40 flips, about how many heads are predicted in 200 flips?','["120", "40", "60", "12"]'::jsonb,2,'12/40 = 0.3, and 0.3 × 200 = 60.','original'),
('111.30.c.6.D',3,'A fair die is rolled twice. What is the probability of getting a 6 both times?','["2/6", "1/6", "1/12", "1/36"]'::jsonb,3,'1/6 × 1/6 = 1/36.','original'),
('111.30.c.6.D',3,'A bag has 3 red and 5 blue marbles. One marble is drawn. What is the probability it is red?','["3/8", "5/8", "3/5", "1/3"]'::jsonb,0,'3 favorable out of 8 total.','original'),
('111.30.c.6.E',3,'The probability of rain is 0.35. What is the probability it does NOT rain?','["0.35", "0.65", "0.55", "1.35"]'::jsonb,1,'The complement is 1 - 0.35.','original'),
('111.30.c.6.E',3,'If an event has probability 2/7, its complement has probability:','["7/2", "1/7", "5/7", "2/7"]'::jsonb,2,'Event and complement sum to 1.','original'),
('111.30.c.6.F',3,'Which event is least likely?','["probability 0.95", "probability 0.5", "probability 0.75", "probability 0.05"]'::jsonb,3,'The smallest probability is least likely.','original'),
('111.30.c.6.F',3,'After 100 trials, event A happened 30 times and event B happened 45 times. Which comparison is supported?','["B has the greater experimental probability.", "Neither can be compared.", "A has the greater experimental probability.", "They are equal."]'::jsonb,0,'45/100 > 30/100.','original'),
('111.30.c.6.G',4,'A fair coin is flipped twice. The theoretical probability of two heads is 1/4. In 80 trials, about how many two-head results are expected?','["10", "20", "40", "60"]'::jsonb,1,'1/4 × 80 = 20.','original'),
('111.30.c.6.G',3,'A student''s experiment gives 24 two-head outcomes in 80 trials. How does this compare with the theoretical probability?','["It is much lower than 1/4.", "It is exactly 1/4.", "It is close but slightly higher than 1/4.", "It cannot be compared."]'::jsonb,2,'24/80 = 0.30 and 1/4 = 0.25.','original'),
('111.30.c.7.A',3,'Which inequality is graphed with a closed circle at 3 and a ray going right?','["x > 3", "x ≤ 3", "x < 3", "x ≥ 3"]'::jsonb,3,'Closed circle includes 3 and right means greater.','original'),
('111.30.c.7.A',3,'Which number line graph shows 2x + 1 < 9?','["an open circle at 4 and a ray going left", "a closed circle at 4 and a ray going left", "a closed circle at 5 and a ray going right", "an open circle at 4 and a ray going right"]'::jsonb,0,'2x < 8 gives x < 4.','original'),
('111.30.c.7.B',4,'Solve: -3x + 2 > 14','["x > 4", "x < -4", "x < 4", "x > -4"]'::jsonb,1,'-3x > 12; dividing by a negative flips the sign.','original'),
('111.30.c.7.B',3,'Solve: 4x - 5 ≤ 11','["x ≥ 4", "x ≤ 24", "x ≤ 4", "x ≤ 1.5"]'::jsonb,2,'4x ≤ 16 and x ≤ 4.','original'),
('111.30.c.7.C',3,'Two gyms: A charges $30 plus $5 per visit and B charges $10 plus $9 per visit. Which equation finds the visits v where cost is equal?','["30 + 9v = 10 + 5v", "30v + 5 = 10v + 9", "30 + 10 = 5v + 9v", "30 + 5v = 10 + 9v"]'::jsonb,3,'Set the two cost expressions equal.','original'),
('111.30.c.7.C',4,'A plant is 4 inches tall and grows 2 inches each week. Another is 10 inches and grows 1 inch each week. Which inequality finds when the first is taller?','["4 + 2w > 10 + w", "4 + 2w < 10 + w", "4 + w > 10 + 2w", "4w + 2 > 10w + 1"]'::jsonb,0,'Compare heights after w weeks.','original'),
('111.30.c.7.D',4,'Which situation matches 3x + 8 = 5x - 2?','["Three friends buy 8 items and 5 friends buy 2.", "Two plans cost the same: a $8 fee with $3 per use and a $2 credit with $5 per use.", "Both amounts are subtracted.", "A bus carries 8 more than 3 people."]'::jsonb,1,'Each side is a fixed amount plus a rate.','original'),
('111.30.c.7.D',4,'Which real-world problem matches 2x - 6 < x + 4?','["A person pays x for 4 items.", "Two items cost 6 each.", "A cost of 2 per item minus a 6 discount is less than 1 per item plus a 4 fee.", "Half of x is 6."]'::jsonb,2,'Each side is a linear cost.','original'),
('111.30.c.7.E',3,'Solve: 5x + 3 = 2x + 18','["x = 21/5", "x = 7", "x = 3", "x = 5"]'::jsonb,3,'3x = 15.','original'),
('111.30.c.8.A',3,'A table shows (2, 7) and (4, 14). What is the constant of proportionality k = y/x?','["3.5", "5", "0.29", "7"]'::jsonb,0,'7 ÷ 2 = 3.5.','original'),
('111.30.c.8.A',3,'Cheese costs $6 for 4 pounds at a constant rate. What is k, the cost per pound?','["2", "1.5", "0.67", "24"]'::jsonb,1,'6 ÷ 4 = 1.5.','original'),
('111.30.c.8.B',3,'Which equation represents a proportional relationship?','["y = 2.5x + 1", "y = 2 - x", "y = 2.5x", "y = x²"]'::jsonb,2,'Proportional equations have the form y = kx.','original'),
('111.30.c.8.B',3,'A graph is a straight line that does NOT pass through the origin. This relationship is:','["a constant of 0", "proportional", "undefined", "non-proportional"]'::jsonb,3,'Proportional graphs pass through (0, 0).','original'),
('111.30.c.8.C',3,'Which situation is NOT proportional?','["a taxi that charges $4 plus $2 per mile", "walking at a constant speed from rest", "a recipe that scales with servings", "buying apples at a set price per pound"]'::jsonb,0,'A flat starting fee breaks proportionality.','original'),
('111.30.c.9',3,'A line has the equation y = 3x + 2. What is the y-value when x = 4?','["11", "14", "24", "12"]'::jsonb,1,'3(4) + 2 = 14.','original'),
('111.30.c.9',3,'A savings plan is y = 50x + 120 where x is weeks. What does 120 represent?','["the savings each week", "the number of weeks", "the starting amount", "the final total"]'::jsonb,2,'The constant term is the amount when x = 0.','original'),
('111.30.c.10.A',3,'Cutting a circle into thin wedges and arranging them in a row forms a shape close to a parallelogram. What formula does this model?','["V = πr²h", "A = 2πr", "C = 2πr", "A = πr²"]'::jsonb,3,'The shape has base half the circumference and height r.','original'),
('111.30.c.10.A',3,'Wrapping a string around a circle and comparing to the diameter models which formula?','["C = πd", "C = d²", "A = r²", "A = πd"]'::jsonb,0,'Circumference is pi times diameter.','original'),
('111.30.c.10.B',3,'A rectangular prism is 5 by 3 by 2. What is its total surface area?','["31 square units", "62 square units", "30 square units", "20 square units"]'::jsonb,1,'2(15 + 10 + 6) = 62.','original'),
('111.30.c.10.B',4,'A square pyramid has a base side of 6 and four triangular faces each with base 6 and slant height 5. What is its lateral area?','["30 square units", "96 square units", "60 square units", "120 square units"]'::jsonb,2,'4 × 1/2 × 6 × 5 = 60.','original'),
('111.30.c.10.C',3,'The volume of a cylinder is found by multiplying the area of the base by:','["the circumference", "the radius", "the diameter", "the height"]'::jsonb,3,'V = Bh.','original'),
('111.30.c.10.C',3,'A cylinder''s base area is 12 square cm and its height is 5 cm. What is its volume?','["60 cubic cm", "17 cubic cm", "30 cubic cm", "120 cubic cm"]'::jsonb,0,'12 × 5 = 60.','original'),
('111.30.c.10.D',3,'A rectangular pyramid and a rectangular prism have congruent bases and equal heights. How do their volumes compare?','["They are equal.", "The pyramid holds 1/3 as much.", "The pyramid holds twice as much.", "The pyramid holds 1/2 as much."]'::jsonb,1,'Three pyramids fill one prism.','original'),
('111.30.c.10.D',3,'How many pyramids with the same base and height fill one rectangular prism?','["6", "2", "3", "4"]'::jsonb,2,'V(pyramid) = 1/3 Bh.','original'),
('111.30.c.10.E',3,'A triangular pyramid has 1/3 the volume of a triangular prism with congruent bases and equal heights. If the prism volume is 90, the pyramid volume is:','["45", "60", "270", "30"]'::jsonb,3,'90 ÷ 3 = 30.','original'),
('111.30.c.10.E',3,'The volume formula for a triangular pyramid is V =','["1/3 Bh", "Bh", "1/2 Bh", "3Bh"]'::jsonb,0,'B is the area of the triangular base.','original'),
('111.30.c.10.F',3,'A cone and a cylinder have congruent bases and equal heights. How many cones of water fill the cylinder?','["2", "3", "4", "1"]'::jsonb,1,'A cone is 1/3 of the cylinder.','original'),
('111.30.c.10.F',3,'A cylinder holds 120 cubic cm. A cone with the same base and height holds:','["240 cubic cm", "60 cubic cm", "40 cubic cm", "360 cubic cm"]'::jsonb,2,'120 ÷ 3 = 40.','original'),
('111.30.c.10.G',3,'Squares are built on the sides of a right triangle. Which statement explains the Pythagorean theorem?','["Only the hypotenuse is squared.", "All three squares have the same area.", "The largest square is half the smallest.", "The two smaller squares'' areas add to the largest square''s area."]'::jsonb,3,'a² + b² = c².','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'ms_madv7_v1'
from (values
('111.30.c.10.G',3,'In a right triangle, the hypotenuse is the side:','["opposite the right angle", "always equal to a leg", "shortest of the three", "adjacent to the right angle"]'::jsonb,0,'It is the longest side across from the 90° angle.','original'),
('111.30.c.10.H',3,'The exterior angle of a triangle equals the sum of:','["all three interior angles", "the two nonadjacent interior angles", "the adjacent interior angle", "180 degrees"]'::jsonb,1,'An exterior angle equals the remote interior angles added.','original'),
('111.30.c.10.H',3,'Two parallel lines are cut by a transversal. Alternate interior angles are:','["complementary", "supplementary", "congruent", "unrelated"]'::jsonb,2,'Alternate interior angles are equal.','original'),
('111.30.c.11.A',3,'A circle has radius 7 cm. Using 22/7 for pi, what is its circumference?','["49 cm", "22 cm", "154 cm", "44 cm"]'::jsonb,3,'2 × 22/7 × 7 = 44.','original'),
('111.30.c.11.A',3,'What is the area of a circle with a radius of 5 in., leaving the answer in terms of pi?','["25π square inches", "50π square inches", "5π square inches", "10π square inches"]'::jsonb,0,'A = πr².','original'),
('111.30.c.11.B',3,'A figure is a 6 by 4 rectangle with a triangle of base 6 and height 3 on top. What is the total area?','["42 square units", "33 square units", "24 square units", "27 square units"]'::jsonb,1,'24 + 9 = 33.','original'),
('111.30.c.11.B',4,'A 10 by 8 rectangle has a 4 by 3 rectangle cut out. What is the remaining area?','["92 square units", "12 square units", "68 square units", "80 square units"]'::jsonb,2,'80 - 12 = 68.','original'),
('111.30.c.11.C',4,'The lateral area of a prism is found by multiplying the base perimeter by:','["the base area", "the radius", "the slant height only", "the height"]'::jsonb,3,'The sides unroll into a rectangle.','original'),
('111.30.c.11.C',4,'A triangular prism has a base perimeter of 12 and a height of 7. What is its lateral area?','["84 square units", "168 square units", "42 square units", "19 square units"]'::jsonb,0,'12 × 7 = 84.','original'),
('111.30.c.11.D',3,'A rectangular pyramid has a 6 by 5 base and a height of 9. What is its volume?','["270 cubic units", "90 cubic units", "30 cubic units", "45 cubic units"]'::jsonb,1,'1/3 × 30 × 9 = 90.','original'),
('111.30.c.11.D',4,'A triangular pyramid has base area 24 and volume 80. What is its height?','["3.33", "20/3", "10", "30"]'::jsonb,2,'80 = 1/3 × 24 × h.','original'),
('111.30.c.11.E',3,'A cylinder has radius 3 and height 10. What is its volume in terms of pi?','["60π cubic units", "30π cubic units", "180π cubic units", "90π cubic units"]'::jsonb,3,'π × 9 × 10.','original'),
('111.30.c.11.E',4,'What is the volume of a sphere with radius 3, in terms of pi?','["36π cubic units", "108π cubic units", "27π cubic units", "12π cubic units"]'::jsonb,0,'4/3 π r³ = 4/3 × 27π.','original'),
('111.30.c.11.E',3,'A cone has radius 6 and height 5. What is its volume in terms of pi?','["30π cubic units", "60π cubic units", "180π cubic units", "90π cubic units"]'::jsonb,1,'1/3 × 36π × 5.','original'),
('111.30.c.11.F',3,'A right triangle has legs 9 and 12. What is the hypotenuse?','["3", "21", "15", "108"]'::jsonb,2,'81 + 144 = 225.','original'),
('111.30.c.11.F',4,'Sides 7, 24 and 25: does this triangle contain a right angle?','["Yes, because all sides are positive.", "No, because 25 is odd.", "No, because 7 + 24 is not 25.", "Yes, because 49 + 576 = 625."]'::jsonb,3,'The converse of the Pythagorean theorem confirms it.','original'),
('111.30.c.11.G',4,'Points (0, 0) and (5, 12) are plotted. What is the distance between them?','["13", "7", "60", "17"]'::jsonb,0,'25 + 144 = 169.','original'),
('111.30.c.12.A',3,'Which transformation can change the size of a figure?','["rotation", "dilation", "reflection", "translation"]'::jsonb,1,'Only dilations enlarge or shrink.','original'),
('111.30.c.12.A',3,'After a translation, the image and original have:','["opposite orientation", "different sizes", "the same size, shape and orientation", "different shapes"]'::jsonb,2,'A slide preserves everything.','original'),
('111.30.c.12.B',3,'Which transformations always produce a congruent image?','["dilations only", "none of them", "dilations and reflections", "translations, reflections and rotations"]'::jsonb,3,'Rigid motions preserve size and shape.','original'),
('111.30.c.12.B',3,'A figure is dilated by a scale factor of 2. The image is:','["similar but not congruent", "a translation", "congruent", "a reflection"]'::jsonb,0,'Side lengths double.','original'),
('111.30.c.12.C',3,'Reflect (3, -2) over the x-axis. Where does it land?','["(2, 3)", "(3, 2)", "(-3, -2)", "(-3, 2)"]'::jsonb,1,'Reflecting over the x-axis changes the y sign.','original'),
('111.30.c.12.C',4,'Rotate (4, 1) 90° counterclockwise about the origin. Where does it land?','["(1, 4)", "(-4, -1)", "(-1, 4)", "(1, -4)"]'::jsonb,2,'(x, y) becomes (-y, x).','original'),
('111.30.c.12.D',4,'A square has side 4 and is dilated by scale factor 3. What is the area of the image?','["36 square units", "16 square units", "48 square units", "144 square units"]'::jsonb,3,'New side is 12 and 12² = 144.','original'),
('111.30.c.12.D',3,'A figure is dilated by scale factor 2. Its perimeter becomes:','["twice as large", "the same", "half as large", "four times as large"]'::jsonb,0,'Linear measures multiply by the scale factor.','original'),
('111.30.c.13.A',3,'Which is the best way to choose a random sample of students for a survey?','["ask only the first ten in line", "draw names from a hat containing every student", "ask only your friends", "ask only the athletes"]'::jsonb,1,'Random choice gives each student the same chance.','original'),
('111.30.c.13.A',3,'In a random sample of 50 students, 30 prefer pizza. About what fraction of a population of 500 prefers pizza?','["1/5", "30/500", "3/5", "3/50"]'::jsonb,2,'30/50 = 3/5.','original'),
('111.30.c.13.B',3,'Sample X has a mean of 82 and sample Y has a mean of 75, with similar spreads. What can be inferred?','["They are identical.", "Y is certainly higher.", "No comparison is possible.", "Population X tends to score higher than Y."]'::jsonb,3,'Compare centers when spreads are alike.','original'),
('111.30.c.13.B',4,'Two samples have the same mean but sample A has much wider spread. Which statement is correct?','["Sample B''s values are more consistent.", "Sample A''s values are more consistent.", "Sample A has no data.", "Their spreads are equal."]'::jsonb,0,'A narrower spread means less variability.','original'),
('111.30.c.13.C',4,'Why generate many random samples of the same size from a known population?','["to avoid collecting data", "to see how much sample results vary", "to choose a biased sample", "to make results equal"]'::jsonb,1,'Repeated sampling shows variability.','original'),
('111.30.c.13.C',3,'As a random sample gets larger, its results usually:','["become biased", "vary more", "vary less around the population value", "stop reflecting the population"]'::jsonb,2,'Larger samples are more consistent.','original'),
('111.30.c.13.D',4,'What is the mean absolute deviation of 2, 4, 6, 8?','["1", "4", "5", "2"]'::jsonb,3,'Mean is 5; deviations are 3, 1, 1, 3 and average 2.','original'),
('111.30.c.13.D',3,'A smaller mean absolute deviation means the data are:','["closer to the mean on average", "farther from the mean", "all equal", "always larger"]'::jsonb,0,'MAD measures average distance from the mean.','original'),
('111.30.c.14.A',3,'A budget has income $2,400, savings $300, rent $900 and other expenses $1,000. How much is left unplanned?','["$300", "$200", "$0", "$1,500"]'::jsonb,1,'2,400 - 300 - 900 - 1,000 = 200.','original'),
('111.30.c.14.A',3,'Which is part of a personal budget?','["a shoe size", "a vacation photo", "emergency savings", "a favorite color"]'::jsonb,2,'Budgets include planned savings.','original'),
('111.30.c.14.B',3,'A family budget estimator is used to find the minimum amount a family needs to cover:','["only entertainment", "only luxuries", "only taxes", "basic household costs such as housing, food and transportation"]'::jsonb,3,'It estimates necessary monthly costs.','original'),
('111.30.c.14.B',4,'A family needs $4,800 a month and one adult works 160 hours a month. What hourly wage is needed?','["$30", "$20", "$48", "$160"]'::jsonb,0,'4,800 ÷ 160 = 30.','original'),
('111.30.c.14.C',3,'Which is a financially responsible choice?','["spending all income each month", "saving some money from each paycheck", "skipping a bill to buy a gadget", "taking credit without reading terms"]'::jsonb,1,'Building savings supports future needs.','original'),
('111.30.c.14.C',3,'A person with limited income wants a $1,200 phone. Which is the most responsible plan?','["borrow on a high-interest card", "buy it and hope to pay later", "save for several months before buying", "skip rent"]'::jsonb,2,'Planning avoids costly debt.','original')
